class NaiveCache<K, V> {
    private final int capacity;
    private final Map<K, V> data = new HashMap<>();
    private final Map<K, Long> lastAccess = new HashMap<>();

    NaiveCache(int capacity) { this.capacity = capacity; }

    public synchronized V get(K key) {
        V v = data.get(key);
        if (v == null) return null;
        lastAccess.put(key, System.nanoTime());
        return v;
    }
    public synchronized void put(K key, V value) {
        if (!data.containsKey(key) && data.size() >= capacity) {
            K lru = null; long oldest = Long.MAX_VALUE;
            for (Map.Entry<K, Long> e : lastAccess.entrySet()) {
                if (e.getValue() < oldest) { oldest = e.getValue(); lru = e.getKey(); }
            }
            if (lru != null) { data.remove(lru); lastAccess.remove(lru); }
        }
        data.put(key, value);
        lastAccess.put(key, System.nanoTime());
    }
}

