import java.util.*;
import java.util.concurrent.locks.ReentrantLock;

public class LRUCache<K, V> {
    private static class Node<K, V> {
        K key; V value; long expiryAt; // Long.MAX_VALUE = no expiry
        Node<K,V> prev, next;
        Node(K k, V v, long e) { key = k; value = v; expiryAt = e; }
    }
    private final int capacity;
    private final Map<K, Node<K,V>> map;
    private final Node<K,V> head, tail; // dummy sentinels
    private final ReentrantLock lock = new ReentrantLock();

    public LRUCache(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("capacity > 0");
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.head = new Node<>(null, null, 0);
        this.tail = new Node<>(null, null, 0);
        head.next = tail; tail.prev = head;
    }
    private boolean isExpired(Node<K,V> n, long now) {
        return n.expiryAt != Long.MAX_VALUE && now >= n.expiryAt;
    }
    private void unlink(Node<K,V> n) {
        n.prev.next = n.next; n.next.prev = n.prev;
    }
    private void addFirst(Node<K,V> n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
    private void moveToHead(Node<K,V> n) { unlink(n); addFirst(n); }

    public V get(K key) {
        Objects.requireNonNull(key);
        lock.lock();
        try {
            Node<K,V> n = map.get(key);
            if (n == null) return null;
            if (isExpired(n, System.currentTimeMillis())) {
                unlink(n); map.remove(key); // lazy reclaim
                return null;
            }
            moveToHead(n); // LRU: read is a write
            return n.value;
        } finally { lock.unlock(); }
    }
    public void put(K key, V value) { put(key, value, 0); }

    public void put(K key, V value, long ttlMillis) {
        Objects.requireNonNull(key); Objects.requireNonNull(value);
        long expiry = ttlMillis <= 0 ? Long.MAX_VALUE
            : System.currentTimeMillis() + ttlMillis;
        lock.lock();
        try {
            Node<K,V> n = map.get(key);
            if (n != null) {
                n.value = value; n.expiryAt = expiry;
                moveToHead(n);
                return;
            }
            Node<K,V> fresh = new Node<>(key, value, expiry);
            map.put(key, fresh); addFirst(fresh);
            // Reclaim expired LRU first, then enforce capacity.
            // Keeps size() honest without a cleaner thread.
            evictIfNeeded();
        } finally { lock.unlock(); }
    }
    private void evictIfNeeded() {
        long now = System.currentTimeMillis();
        // Drop expired tail entries for free while we are here.
        Node<K,V> cur = tail.prev;
        while (cur != head && isExpired(cur, now)) {
            Node<K,V> p = cur.prev;
            unlink(cur); map.remove(cur.key);
            cur = p;
        }
        while (map.size() > capacity) {
            Node<K,V> lru = tail.prev;
            unlink(lru); map.remove(lru.key);
        }
    }
    public void remove(K key) {
        lock.lock();
        try { Node<K,V> n = map.remove(key); if (n != null) unlink(n); }
        finally { lock.unlock(); }
    }
    public int size() {
        lock.lock();
        try { return map.size(); }
        finally { lock.unlock(); }
    }
}
